      { badge: "VAIHE 2", title: "💡 Tarinan aihe tai idea", desc: "Kirjoita aihe — tai paina \"Puhu\" sanellaksesi ideasi ääneen!", tip: "Vinkki: Jo kahdesta sanasta syntyy rikas tarina." },
      { badge: "VAIHE 3", title: "📊 Vaikeustaso ja erikoisalat", desc: "Valitse Alkeista Mestariin (C2+) ja avaa esim. laki tai lääketiede.", tip: "Vinkki: Aloittelijat saavat selkeät lauserakenteet." },
      { badge: "VAIHE 4", title: "📖 Muoto ja Tieto vs Fiktio", desc: "Valitse kertomus tai kahden hengen dialogi, tieto tai fiktio!", tip: "Vinkki: Dialogeissa on kaksi erillistä puheääntä!" },
      { badge: "VAIHE 5", title: "🚀 Paina Luo tarina!", desc: "Valmis? Napsauta \"Luo tarina\" saadaksesi äänen, käännökset ja tehtävät.", tip: "Vinkki: Jaa tarinoita ystäville yhdellä napsautuksella!" }
