      { badge: "HARJOITUS 3", title: "📚 Opiskeluarkit ja kielioppi", desc: "Tulosta tehtäviä, tutki verbitaivutuksia ja kielioppihuomioita.", tip: "Vinkki: Napauta mitä tahansa sanaa nähdäksesi etymologian!" }
